//! Prepared emacs-mule encoder parity against GNU Emacs.
//! Expectations must be refreshed from GNU with NEOVM_ORACLE_MODE=refresh
//! UPDATE_EXPECT=1; all answers are generated by GNU, never hand-written.
//! Decoder charset properties and malformed-byte divergences are outside this
//! encoder change and are documented in the lane report.

use crate::common::{
    assert_oracle_parity_with_env_expect, return_if_neovm_enable_oracle_proptest_not_set,
};

#[test]
fn mule_prepared_encode_unicode_and_unmappable() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK ((nil nil nil) ((65 83 67 73 73) (65 83 67 73 73) nil) ((233 224 252) (129 233 129 224 129 252) nil) ((1055 1088 1080 1074 1077 1090) (140 191 140 224 140 216 140 210 140 213 140 226) nil) ((917 955 955 940 948 945) (134 197 134 235 134 235 134 220 134 228 134 225) nil) ((26085 26412 35486) (145 200 213 145 177 190 149 235 163) nil) ((20013 25991) (145 214 208 145 206 196) nil) ((54620 44397 50612) (147 199 209 147 177 185 147 190 238) nil) ((97 233 1078 26085 10) (97 129 233 140 214 145 200 213 10) nil) ((128512) (32) nil))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(mapcar (lambda (s) (let ((e (encode-coding-string s 'emacs-mule))) (list (string-to-list s) (string-to-list e) (multibyte-string-p e)))) '("" "ASCII" "éàü" "Привет" "Ελλάδα" "日本語" "中文" "한국어" "aéж日\n" "😀"))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_unibyte_and_raw_bytes() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK (((65 128 233 255) nil (65 128 233 255) nil) ((65 4194176 4194281 4194303) t (65 128 233 255) nil) ((65 4194176 4194281 4194303) t (65 128 233 255) nil) ((195 169) nil (129 233) nil))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(mapcar (lambda (s) (let ((e (encode-coding-string s 'emacs-mule))) (list (string-to-list s) (multibyte-string-p s) (string-to-list e) (multibyte-string-p e)))) (list (unibyte-string 65 128 233 255) (string-as-multibyte (unibyte-string 65 128 233 255)) (string 65 #x3fff80 #x3fffe9 #x3fffff) (unibyte-string #xc3 #xa9)))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_aliases_and_eol() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK ((emacs-mule (129 233 10 140 214 10) nil emacs-mule) (emacs-mule-unix (129 233 10 140 214 10) nil emacs-mule-unix) (emacs-mule-dos (129 233 13 10 140 214 13 10) nil emacs-mule-dos) (emacs-mule-mac (129 233 13 140 214 13) nil emacs-mule-mac) (cl2-mule-alias (129 233 10 140 214 10) nil cl2-mule-alias))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(progn (define-coding-system-alias 'cl2-mule-alias 'emacs-mule) (mapcar (lambda (coding) (let ((e (encode-coding-string "é\nж\n" coding))) (list coding (string-to-list e) (multibyte-string-p e) last-coding-system-used))) '(emacs-mule emacs-mule-unix emacs-mule-dos emacs-mule-mac cl2-mule-alias)))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_nocopy_and_source_properties() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK ((nil (129 233 140 214) (face bold) nil) (t (129 233 140 214) (face bold) nil))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(mapcar (lambda (nocopy) (let* ((s (propertize "éж" 'face 'bold)) (e (encode-coding-string s 'emacs-mule nocopy))) (list nocopy (string-to-list e) (text-properties-at 0 s) (text-properties-at 0 e)))) '(nil t))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_ignores_string_charset_annotations() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK ((latin-iso8859-1 (129 233 129 233) latin-iso8859-1) (latin-iso8859-2 (129 233 129 233) latin-iso8859-2) (latin-iso8859-15 (129 233 129 233) latin-iso8859-15) (japanese-jisx0208 (129 233 129 233) japanese-jisx0208) (unicode (129 233 129 233) unicode) (no-such-charset (129 233 129 233) no-such-charset))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(mapcar
  (lambda (cs)
    (let* ((s (propertize "éé" 'charset cs))
           (encoded (encode-coding-string s 'emacs-mule)))
      (list cs (string-to-list encoded) (get-text-property 0 'charset s))))
  '(latin-iso8859-1 latin-iso8859-2 latin-iso8859-15 japanese-jisx0208 unicode no-such-charset))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_runtime_definition_alias_and_redefinition() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[r#""OK (223 (154 223 161) 33 (154 223 161) (32))""#]];
    assert_oracle_parity_with_env_expect(
        r##"(let ((id 223)) (while (aref emacs-mule-charset-table id) (setq id (1- id))) (define-charset 'cl2-mule-custom "cl2" :dimension 1 :code-space [33 126] :code-offset #x1f300 :emacs-mule-id id) (define-charset-alias 'cl2-mule-custom-alias 'cl2-mule-custom) (let ((before (encode-coding-string (string #x1f300) 'emacs-mule))) (define-charset 'cl2-mule-custom "updated" :dimension 1 :code-space [33 126] :code-offset #x1f400 :emacs-mule-id id) (list id (string-to-list before) (encode-char #x1f400 'cl2-mule-custom-alias) (string-to-list (encode-coding-string (string #x1f400) 'emacs-mule)) (string-to-list (encode-coding-string (string #x1f300) 'emacs-mule)))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_follows_latin_priority_changes() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[r#""OK ((129 233) (130 233) (129 233))""#]];
    assert_oracle_parity_with_env_expect(
        r##"(let ((default (encode-coding-string "é" 'emacs-mule))) (set-charset-priority 'latin-iso8859-2) (let ((preferred (encode-coding-string "é" 'emacs-mule))) (set-charset-priority 'latin-iso8859-1) (list (string-to-list default) (string-to-list preferred) (string-to-list (encode-coding-string "é" 'emacs-mule)))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_follows_jis1978_priority_changes() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[r#""OK ((145 200 213) (144 198 252))""#]];
    assert_oracle_parity_with_env_expect(
        r##"(let ((before (encode-coding-string "日" 'emacs-mule)))
  (set-charset-priority 'japanese-jisx0208-1978)
  (let ((after (encode-coding-string "日" 'emacs-mule)))
    (list (string-to-list before) (string-to-list after))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_preserves_definition_order_before_priority_change() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect =
        expect_test::expect![[r#""OK (223 (156 243 245 191) (156 243 245 191) (154 223 161))""#]];
    assert_oracle_parity_with_env_expect(
        r##"(let ((id 223) (ch #xffff))
  (while (aref emacs-mule-charset-table id) (setq id (1- id)))
  (let ((before (encode-coding-string (string ch) 'emacs-mule)))
    (define-charset 'cl2-mule-overlap "overlapping ordinary charset"
      :dimension 1 :code-space [33 126] :code-offset #xffff :emacs-mule-id id)
    (let ((after-definition (encode-coding-string (string ch) 'emacs-mule)))
      (set-charset-priority 'cl2-mule-overlap)
      (let ((after-priority (encode-coding-string (string ch) 'emacs-mule)))
        (list id (string-to-list before) (string-to-list after-definition)
              (string-to-list after-priority))))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_follows_charset_alias_priority() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[r#""OK ((129 233) (130 233) (129 233))""#]];
    assert_oracle_parity_with_env_expect(
        r##"(progn
  (define-charset-alias 'cl2-mule-latin1-alias 'latin-iso8859-1)
  (define-charset-alias 'cl2-mule-latin2-alias 'latin-iso8859-2)
  (set-charset-priority 'latin-iso8859-1)
  (let ((before (encode-coding-string "é" 'emacs-mule)))
    (set-charset-priority 'cl2-mule-latin2-alias)
    (let ((second (encode-coding-string "é" 'emacs-mule)))
      (set-charset-priority 'cl2-mule-latin1-alias 'latin-iso8859-1)
      (list (string-to-list before) (string-to-list second)
            (string-to-list (encode-coding-string "é" 'emacs-mule))))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}

#[test]
fn mule_prepared_encode_preserves_identity_after_existing_name_alias_collision() {
    return_if_neovm_enable_oracle_proptest_not_set!();
    let expect = expect_test::expect![[
        r#""OK ((129 233 129 181) (129 233 129 181) (130 233 129 181) (130 233 129 181))""#
    ]];
    assert_oracle_parity_with_env_expect(
        r##"(let ((before (encode-coding-string "éµ" 'emacs-mule)))
  (define-charset-alias 'latin-iso8859-1 'latin-iso8859-2)
  (let ((after-alias (encode-coding-string "éµ" 'emacs-mule)))
    (set-charset-priority 'latin-iso8859-1)
    (let ((after-priority (encode-coding-string "éµ" 'emacs-mule)))
      (set-charset-priority 'ascii)
      (list (string-to-list before) (string-to-list after-alias)
            (string-to-list after-priority)
            (string-to-list (encode-coding-string "éµ" 'emacs-mule))))))"##,
        &[("NEOVM_EMACS_MULE_PREPARED", "on")],
        expect,
    );
}
